export function Rbac({
  userName = "{{userName}}",
  role = "{{role}}",
  accent = "{{accent}}",
  showRoleDesc = {{showRoleDesc}},
}) {
  const desc = {
    viewer: "Viewer role grants: read-only access",
    editor: "Editor role grants: read + write access",
    admin: "Admin role grants: read + write + manage users",
  }[role];
  const active = { view: role === "viewer" || role === "editor" || role === "admin", edit: role === "editor" || role === "admin", manage: role === "admin" };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 8px" }}><strong>{userName}</strong> is assigned role <span style={{ fontSize: 10, textTransform: "uppercase", padding: "2px 8px", borderRadius: 999, fontWeight: 700, background: accent }}>{role}</span></p>
      {showRoleDesc && <p style={{ margin: "0 0 10px", fontSize: 11, color: "#24143099" }}>{desc}</p>}
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        <li style={{ padding: "4px 0", fontSize: 12 }}>{active.view ? "✓ View content" : <span style={{ color: "#24143099" }}>&#10005; View content (not granted)</span>}</li>
        <li style={{ padding: "4px 0", fontSize: 12 }}>{active.edit ? "✓ Edit content" : <span style={{ color: "#24143099" }}>&#10005; Edit content (not granted)</span>}</li>
        <li style={{ padding: "4px 0", fontSize: 12 }}>{active.manage ? "✓ Manage users" : <span style={{ color: "#24143099" }}>&#10005; Manage users (not granted)</span>}</li>
      </ul>
    </div>
  );
}
